<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/src/bootstrap.php'; require_admin(); require_once dirname(__DIR__,2).'/src/admin_layout.php';
$fields=['full_name','headline','introduction','biography','goals','interests','email','phone','location','facebook_url'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $values=[]; foreach($fields as $field) $values[$field]=trim((string)($_POST[$field]??''));
 if($values['full_name']===''||$values['headline']===''||($values['email']!==''&&!filter_var($values['email'],FILTER_VALIDATE_EMAIL))||($values['facebook_url']!==''&&!filter_var($values['facebook_url'],FILTER_VALIDATE_URL))){flash('error','Enter a name and headline, a valid email, and a valid profile URL.');redirect('admin/profile.php');}
 try{$photo=upload_image($_FILES['profile_image']??[],'profile');$sql='UPDATE personal_information SET full_name=?,headline=?,introduction=?,biography=?,goals=?,interests=?,email=?,phone=?,location=?,facebook_url=?'.($photo?',profile_image=?':'').' WHERE id=(SELECT id FROM (SELECT id FROM personal_information ORDER BY id LIMIT 1) AS p)';$args=array_values($values);if($photo)$args[]=$photo;$stmt=db()->prepare($sql);$stmt->execute($args);flash('success','Personal information saved.');}catch(Throwable $ex){flash('error',$ex->getMessage());}redirect('admin/profile.php');
}
$p=db()->query('SELECT * FROM personal_information ORDER BY id LIMIT 1')->fetch()?:[];
admin_header('profile.php','Personal information');
?><section class="admin-card"><p class="muted">Edit the profile content shown on the public home and about pages. Changes are stored in MySQL.</p><form method="post" enctype="multipart/form-data" class="admin-form" style="margin-top:1rem"><?= csrf_field() ?><?php foreach($fields as $field): $label=ucwords(str_replace('_',' ',$field));$long=in_array($field,['introduction','biography','goals','interests'],true); ?><label for="<?= e($field) ?>"><?= e($label) ?></label><?php if($long): ?><textarea id="<?= e($field) ?>" name="<?= e($field) ?>" required><?= e($p[$field]??'') ?></textarea><?php else: ?><input id="<?= e($field) ?>" name="<?= e($field) ?>" value="<?= e($p[$field]??'') ?>" <?= $field==='email'?'type="email"':'' ?> <?= in_array($field,['full_name','headline'],true)?'required':'' ?>><?php endif; ?><?php endforeach; ?><label for="profile_image">Profile picture (JPEG, PNG, or WebP; up to 5 MB)</label><?php if(!empty($p['profile_image'])):?><img src="../<?= e($p['profile_image']) ?>" alt="Current profile picture" style="width:120px;height:140px;object-fit:cover"><?php endif; ?><input type="file" id="profile_image" name="profile_image" accept="image/jpeg,image/png,image/webp"><button class="btn btn-primary" type="submit">Save personal information</button></form></section><?php admin_footer(); ?>
